function GrowthFundMainLineCell:SetRightState()
    local canvasGroupR =  KTool.GetComponent(self.GoodNodeRight.gameObject, typeof(CanvasGroup))
    local chargeGetState = self.serverData.payRewardStatus[tostring(self.vo.id)]
    local chargeNotGet = (chargeGetState == Constants.GetStatus.Not)
    local chargeCanGet = (chargeGetState == Constants.GetStatus.Can)
    local chargeHasGet = (chargeGetState == Constants.GetStatus.Has)

    ---@type GoodNodeMB
    local goEnv = CfUtils.GetLuaScr(self.GoodNodeRight, "Game.Behaviours.GoodNodeMB")
    if goEnv then
        goEnv:SetCanGetEffectShow(chargeCanGet)
    end

    local redGoRight = GameUtils.GetRedPointGo(self.GoodNodeRight)
    if redGoRight then
        KTool.SetActive(redGoRight,chargeCanGet)
    end
    KTool.SetActive(self.LockRight.gameObject,( chargeNotGet or not self.isBuy))
    KTool.SetActive(self.FinsihRight.gameObject,chargeHasGet)
    KTool.SetActive(self.UIFX_Right.gameObject,chargeCanGet)
    if chargeHasGet then
        KTool.SetActive(self.TextReceive.gameObject,false)
        KTool.SetActive(self.ImgNotAchieve.gameObject,false)
        self.RewardNumRight.Status = 2
        canvasGroupR.alpha = 0.5
    else
        self.RewardNumRight.Status = 1
        canvasGroupR.alpha = 1
        KTool.SetActive(self.ImgNotAchieve.gameObject,not chargeCanGet)
        KTool.SetActive(self.TextReceive.gameObject,chargeCanGet)
    end
end

function GrowthFundMainLineCell:SetLeftState()
    local canvasGroupL =  KTool.GetComponent(self.GoodNodeLeft.gameObject, typeof(CanvasGroup))
    local freeGetState = self.serverData.freeRewardStatus[tostring(self.vo.id)]
    local freeNotGet = (freeGetState == Constants.GetStatus.Not)
    local freeCanGet = (freeGetState == Constants.GetStatus.Can)
    local freeHasGet = (freeGetState == Constants.GetStatus.Has)

    ---@type GoodNodeMB
    local goEnv = CfUtils.GetLuaScr(self.GoodNodeLeft, "Game.Behaviours.GoodNodeMB")
    if goEnv then
        goEnv:SetCanGetEffectShow(freeCanGet)
    end

    KTool.SetActive(self.LockLeft.gameObject,freeNotGet)
    KTool.SetActive(self.FinsihLeft.gameObject,freeHasGet)


    local redGoLeft = GameUtils.GetRedPointGo(self.GoodNodeLeft)
    if redGoLeft then
        KTool.SetActive(redGoLeft,freeCanGet)
    end

    KTool.SetActive(self.UIFX_Left.gameObject,freeCanGet)
    if freeHasGet then
        self.TextDescLeft.Status = 2
        self.RewardNumLeft.Status = 2
        canvasGroupL.alpha = 0.5
    else
        self.TextDescLeft.Status = 1
        self.RewardNumLeft.Status = 1
        canvasGroupL.alpha = 1
    end

    local lockDes = GameUtils.GetUnlockDescr(self.vo.unlockType, self.vo.unlockId)
    CfUtils.FillText(self.TextDescLeft,lockDes)
    local state = freeCanGet and 2 or 1
    self:SetFrameState(state)
end

function GrowthFundMainLineCell:SetFrameState(status)
    self.ImgFrame1.Status = status
    self.ImgFrame2.Status = status
end

function GrowthFundMainLineCell:SetRewardShow()
    CfUtils.RefeshGoodGo2(self.GoodNodeLeft,self.vo.freeRewardId, nil, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.vo.freeRewardId)
        if goodsVo then
            GameUtils.ShowCommonTipsBoard(self.GoodNodeLeft.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end
    end)
    CfUtils.FillText(self.RewardNumLeft,"x"..self.vo.freeRewardNum)

    CfUtils.RefeshGoodGo2(self.GoodNodeRight,self.vo.ChargeRewardId, nil, nil, nil, function()
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.vo.ChargeRewardId)
        if goodsVo then
            GameUtils.ShowCommonTipsBoard(self.GoodNodeRight.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
        end
    end)
    CfUtils.FillText(self.RewardNumRight,"x"..self.vo.ChargeRewardNum)
end

